from scipy.linalg import logm, expm

def check_counterexample():
    # Try random matrices
    for _ in range(1000):
        A = np.random.randn(2, 2) + 1j * np.random.randn(2, 2)
        B = np.random.randn(2, 2) + 1j * np.random.randn(2, 2)
        # Ensure eigenvalues are not on negative real axis for principal log
        if np.any(np.isreal(np.linalg.eigvals(A))) and np.any(np.linalg.eigvals(A) < 0):
            continue
        try:
            lnA = logm(A)
            lnB = logm(B)
            lnAB = logm(A @ B)
            if np.allclose(lnAB, lnA + lnB, atol=1e-5):
                if not np.allclose(A @ B, B @ A, atol=1e-5):
                    return A, B
        except:
            continue
    return None

res = check_counterexample()
if res is not None:
    A, B = res
    print("Counterexample found!")
    print("A:\n", A)
    print("B:\n", B)
    print("AB:\n", A @ B)
    print("BA:\n", B @ A)
else:
    print("No counterexample found in 1000 tries.")
"}

